#!/bin/bash
set -euo pipefail
exec > >(tee -a /var/log/hw4-startup.log) 2>&1
export DEBIAN_FRONTEND=noninteractive
apt-get -o Acquire::Retries=3 update
apt-get -o DPkg::Lock::Timeout=300 install -y python3-venv
id hw4 >/dev/null 2>&1 || useradd --system --home /opt/hw4 --shell /usr/sbin/nologin hw4
install -d -m 755 /opt/hw4
printf '%s'  | base64 --decode > /opt/hw4/subscriber.py
printf '%s'  | base64 --decode > /opt/hw4/requirements-lock.txt
printf '%s' UFJPSkVDVF9JRD1jdWx0aXZhdGVkLWxpbmstNTA4MjIxLWU2CkJVQ0tFVF9OQU1FPWN1bHRpdmF0ZWQtbGluay01MDgyMjEtZTYtY3M1MjgtaHcyClRPUElDX0lEPWh3NC1mb3JiaWRkZW4tcmVxdWVzdHMKUFlUSE9OVU5CVUZGRVJFRD0xCg== | base64 --decode > /etc/hw4.env
chmod 644 /etc/hw4.env
python3 -m venv /opt/hw4/venv
/opt/hw4/venv/bin/python -m pip install --no-cache-dir -r /opt/hw4/requirements-lock.txt
printf '%s'  | base64 --decode > /etc/systemd/system/hw4-subscriber.service
systemctl daemon-reload
systemctl enable hw4-subscriber.service
systemctl restart hw4-subscriber.service
systemctl is-active hw4-subscriber.service
echo 'HW4 subscriber startup completed'
